    leadingTrivia: Trivia? = nil,
    unexpectedBeforeAttributes: UnexpectedNodesSyntax? = nil,
    attributes: AttributeListSyntax = [],
    unexpectedBetweenAttributesAndModifiers: UnexpectedNodesSyntax? = nil,
