    try self.init(
      leadingTrivia: leadingTrivia,
      unexpectedBeforeAttributes,
      attributes: isolated,
      unexpectedBetweenAttributesAndModifiers,
      modifiers: modifiers,
      unexpectedBetweenModifiersAndCaseKeyword,
      caseKeyword: caseKeyword,unexpectedBetweenCaseKeywordAndElements,
